-- Initial PostgreSQL blueprint; implement as reviewed migrations.
-- Never enable ORM schema synchronization in production.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text, phone_e164 text, password_hash text, display_name text NOT NULL, preferred_locale text NOT NULL DEFAULT 'bn' CHECK (preferred_locale IN ('bn','en')), status text NOT NULL DEFAULT 'pending_verification' CHECK (status IN ('pending_verification','active','suspended','deactivated','deletion_pending')), email_verified_at timestamptz, phone_verified_at timestamptz, last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, CHECK (email IS NOT NULL OR phone_e164 IS NOT NULL));
CREATE UNIQUE INDEX uq_users_email_lower ON users(lower(email)) WHERE email IS NOT NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX uq_users_phone ON users(phone_e164) WHERE phone_e164 IS NOT NULL AND deleted_at IS NULL;
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name_en text NOT NULL, name_bn text NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, description text NOT NULL);
CREATE TABLE user_roles (user_id uuid NOT NULL REFERENCES users(id), role_id uuid NOT NULL REFERENCES roles(id), granted_by uuid REFERENCES users(id), granted_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, PRIMARY KEY(user_id,role_id));
CREATE TABLE role_permissions (role_id uuid NOT NULL REFERENCES roles(id), permission_id uuid NOT NULL REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE auth_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), refresh_token_hash text NOT NULL UNIQUE, user_agent text, ip_hash text, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz, expires_at timestamptz NOT NULL, revoked_at timestamptz, revoke_reason text);
CREATE INDEX ix_auth_sessions_user_active ON auth_sessions(user_id,expires_at) WHERE revoked_at IS NULL;
CREATE TABLE curricula (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name_en text NOT NULL, name_bn text NOT NULL, country_code char(2) NOT NULL DEFAULT 'BD', board_name text, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE education_levels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name_en text NOT NULL, name_bn text NOT NULL, sort_order integer NOT NULL, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name_en text NOT NULL, name_bn text NOT NULL, category text NOT NULL DEFAULT 'academic', is_active boolean NOT NULL DEFAULT true);
CREATE TABLE guardian_student_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guardian_user_id uuid NOT NULL REFERENCES users(id), student_user_id uuid NOT NULL REFERENCES users(id), relationship_type text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','rejected','revoked')), consent_policy_version text, consent_recorded_at timestamptz, verified_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guardian_user_id,student_user_id), CHECK(guardian_user_id<>student_user_id));
CREATE INDEX ix_guardian_links_student_status ON guardian_student_links(student_user_id,status);
CREATE TABLE student_profiles (user_id uuid PRIMARY KEY REFERENCES users(id), date_of_birth date, education_level_id uuid REFERENCES education_levels(id), curriculum_id uuid REFERENCES curricula(id), institution_name text, stream text, district_code text, upazila_code text, learning_goals text, profile_visibility text NOT NULL DEFAULT 'private' CHECK(profile_visibility IN ('private','limited')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tutor_profiles (user_id uuid PRIMARY KEY REFERENCES users(id), headline text, bio text, years_experience smallint CHECK(years_experience>=0), teaching_modes text[] NOT NULL DEFAULT '{}', hourly_rate_minor bigint CHECK(hourly_rate_minor>=0), currency char(3) NOT NULL DEFAULT 'BDT', verification_status text NOT NULL DEFAULT 'not_submitted' CHECK(verification_status IN ('not_submitted','submitted','under_review','needs_information','approved','rejected','suspended','expired')), publication_status text NOT NULL DEFAULT 'draft' CHECK(publication_status IN ('draft','published','unpublished')), response_time_minutes integer CHECK(response_time_minutes>=0), profile_updated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(teaching_modes <@ ARRAY['in_person','online','hybrid']::text[]));
CREATE INDEX ix_tutor_public_search ON tutor_profiles(verification_status,publication_status) WHERE publication_status='published';
CREATE TABLE file_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid REFERENCES users(id), storage_provider text NOT NULL, storage_key text NOT NULL UNIQUE, original_filename text, media_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>=0), checksum_sha256 text, visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','public_approved')), purpose text NOT NULL, malware_scan_status text NOT NULL DEFAULT 'pending' CHECK(malware_scan_status IN ('pending','clean','infected','failed','not_required')), created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE tutor_qualifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), qualification_type text NOT NULL, institution text, title text NOT NULL, issued_year smallint, expires_on date, evidence_asset_id uuid REFERENCES file_assets(id), review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','approved','rejected','expired')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tutor_verification_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), reviewer_user_id uuid NOT NULL REFERENCES users(id), decision text NOT NULL CHECK(decision IN ('approved','rejected','needs_information','suspended','reinstated')), reason_code text NOT NULL, internal_notes text, policy_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_tutor_verification_history ON tutor_verification_reviews(tutor_user_id,created_at DESC);
CREATE TABLE tutor_subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), subject_id uuid NOT NULL REFERENCES subjects(id), education_level_id uuid NOT NULL REFERENCES education_levels(id), curriculum_id uuid REFERENCES curricula(id), stream text, rate_minor bigint CHECK(rate_minor>=0), currency char(3) NOT NULL DEFAULT 'BDT', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tutor_user_id,subject_id,education_level_id,curriculum_id,stream));
CREATE INDEX ix_tutor_subject_lookup ON tutor_subjects(subject_id,education_level_id,curriculum_id);
CREATE TABLE tutor_service_areas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), district_code text NOT NULL, upazila_code text, locality_name text, radius_km numeric(5,2) CHECK(radius_km IS NULL OR radius_km>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_tutor_service_area ON tutor_service_areas(district_code,upazila_code);
CREATE TABLE tutor_availability (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), weekday smallint NOT NULL CHECK(weekday BETWEEN 0 AND 6), start_local time NOT NULL, end_local time NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Dhaka', effective_from date, effective_until date, is_active boolean NOT NULL DEFAULT true, CHECK(end_local>start_local));
CREATE TABLE tutor_blocked_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE TABLE tutor_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_user_id uuid NOT NULL REFERENCES users(id), student_user_id uuid NOT NULL REFERENCES users(id), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), subject_id uuid NOT NULL REFERENCES subjects(id), education_level_id uuid NOT NULL REFERENCES education_levels(id), requested_mode text NOT NULL CHECK(requested_mode IN ('in_person','online','hybrid')), budget_min_minor bigint CHECK(budget_min_minor IS NULL OR budget_min_minor>=0), budget_max_minor bigint CHECK(budget_max_minor IS NULL OR budget_max_minor>=0), currency char(3) NOT NULL DEFAULT 'BDT', preferred_timezone text NOT NULL DEFAULT 'Asia/Dhaka', preferred_schedule jsonb NOT NULL DEFAULT '[]'::jsonb, locality_text text, message text, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','accepted','declined','withdrawn','expired','converted')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(budget_min_minor IS NULL OR budget_max_minor IS NULL OR budget_max_minor>=budget_min_minor));
CREATE INDEX ix_tutor_requests_tutor_status ON tutor_requests(tutor_user_id,status,created_at DESC);
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid REFERENCES tutor_requests(id), requester_user_id uuid NOT NULL REFERENCES users(id), student_user_id uuid NOT NULL REFERENCES users(id), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), subject_id uuid NOT NULL REFERENCES subjects(id), education_level_id uuid NOT NULL REFERENCES education_levels(id), mode text NOT NULL CHECK(mode IN ('in_person','online','hybrid')), status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','accepted','awaiting_payment','confirmed','in_progress','completed','declined','cancelled','expired','disputed','replacement_requested')), price_per_session_minor bigint NOT NULL CHECK(price_per_session_minor>=0), currency char(3) NOT NULL DEFAULT 'BDT', duration_minutes integer NOT NULL CHECK(duration_minutes BETWEEN 15 AND 480), cancellation_policy_version text NOT NULL, service_agreement_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX ix_bookings_tutor_status ON bookings(tutor_user_id,status,created_at DESC);
CREATE INDEX ix_bookings_student_status ON bookings(student_user_id,status,created_at DESC);
CREATE TABLE booking_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), student_user_id uuid NOT NULL REFERENCES users(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Dhaka', status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','in_progress','completed','cancelled','no_show','reschedule_pending')), meeting_url text, location_instructions text, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE INDEX ix_sessions_tutor_start ON booking_sessions(tutor_user_id,starts_at);
CREATE INDEX ix_sessions_student_start ON booking_sessions(student_user_id,starts_at);
ALTER TABLE booking_sessions ADD CONSTRAINT ex_tutor_session_overlap EXCLUDE USING gist (tutor_user_id WITH =, tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE(status IN ('scheduled','in_progress'));
CREATE TABLE session_attendance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES booking_sessions(id), participant_user_id uuid NOT NULL REFERENCES users(id), attendance_status text NOT NULL CHECK(attendance_status IN ('present','late','absent','excused')), recorded_by uuid NOT NULL REFERENCES users(id), recorded_at timestamptz NOT NULL DEFAULT now(), notes text, UNIQUE(session_id,participant_user_id));
CREATE TABLE assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), session_id uuid REFERENCES booking_sessions(id), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), student_user_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, instructions text, due_at timestamptz, status text NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assignment_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id uuid NOT NULL REFERENCES assignments(id), student_user_id uuid NOT NULL REFERENCES users(id), submission_text text, asset_ids uuid[] NOT NULL DEFAULT '{}', submitted_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','late','reviewed','returned')), tutor_feedback text, reviewed_by uuid REFERENCES users(id), reviewed_at timestamptz);
CREATE TABLE assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), student_user_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, assessment_type text NOT NULL, max_score numeric(10,2) CHECK(max_score IS NULL OR max_score>=0), scheduled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assessment_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES assessments(id), score numeric(10,2) CHECK(score IS NULL OR score>=0), feedback text, recorded_by uuid NOT NULL REFERENCES users(id), recorded_at timestamptz NOT NULL DEFAULT now(), revision_number integer NOT NULL DEFAULT 1 CHECK(revision_number>0), UNIQUE(assessment_id,revision_number));
CREATE TABLE progress_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), student_user_id uuid NOT NULL REFERENCES users(id), period_start date NOT NULL, period_end date NOT NULL, strengths text, areas_to_improve text, next_steps text, attendance_summary jsonb NOT NULL DEFAULT '{}'::jsonb, visibility text NOT NULL DEFAULT 'guardian_and_student' CHECK(visibility IN ('student_only','guardian_and_student')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(period_end>=period_start));
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid REFERENCES bookings(id), created_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE TABLE conversation_participants (conversation_id uuid NOT NULL REFERENCES conversations(id), user_id uuid NOT NULL REFERENCES users(id), joined_at timestamptz NOT NULL DEFAULT now(), left_at timestamptz, PRIMARY KEY(conversation_id,user_id));
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id), sender_user_id uuid NOT NULL REFERENCES users(id), body text NOT NULL CHECK(length(body)<=10000), asset_ids uuid[] NOT NULL DEFAULT '{}', sent_at timestamptz NOT NULL DEFAULT now(), edited_at timestamptz, deleted_at timestamptz);
CREATE INDEX ix_messages_conversation_sent ON messages(conversation_id,sent_at DESC);
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), event_type text NOT NULL, title_key text NOT NULL, body_key text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_notifications_user_unread ON notifications(user_id,created_at DESC) WHERE read_at IS NULL;
CREATE TABLE notification_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), notification_id uuid NOT NULL REFERENCES notifications(id), channel text NOT NULL CHECK(channel IN ('in_app','email','sms','push','whatsapp')), provider text, provider_message_id text, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sent','delivered','failed','suppressed')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), last_error_code text, sent_at timestamptz, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(channel,provider,provider_message_id));
CREATE TABLE payment_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), payer_user_id uuid NOT NULL REFERENCES users(id), amount_minor bigint NOT NULL CHECK(amount_minor>0), currency char(3) NOT NULL DEFAULT 'BDT', status text NOT NULL DEFAULT 'created' CHECK(status IN ('created','pending','succeeded','failed','expired','cancelled')), idempotency_key text NOT NULL, provider text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(payer_user_id,idempotency_key));
CREATE TABLE payment_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_order_id uuid NOT NULL REFERENCES payment_orders(id), provider text NOT NULL, provider_transaction_id text, provider_event_id text, amount_minor bigint NOT NULL CHECK(amount_minor>=0), currency char(3) NOT NULL, status text NOT NULL CHECK(status IN ('pending','succeeded','failed','reversed')), verified_at timestamptz, raw_payload_redacted jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_transaction_id), UNIQUE(provider,provider_event_id));
CREATE TABLE refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_order_id uuid NOT NULL REFERENCES payment_orders(id), amount_minor bigint NOT NULL CHECK(amount_minor>0), currency char(3) NOT NULL, reason_code text NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','processing','succeeded','failed','rejected')), requested_by uuid NOT NULL REFERENCES users(id), reviewed_by uuid REFERENCES users(id), provider_refund_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, account_type text NOT NULL CHECK(account_type IN ('asset','liability','equity','revenue','expense')), currency char(3) NOT NULL, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE ledger_journals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_type text NOT NULL, source_id uuid NOT NULL, idempotency_key text NOT NULL UNIQUE, description text NOT NULL, posted_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES users(id));
CREATE TABLE ledger_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), journal_id uuid NOT NULL REFERENCES ledger_journals(id), account_id uuid NOT NULL REFERENCES ledger_accounts(id), direction text NOT NULL CHECK(direction IN ('debit','credit')), amount_minor bigint NOT NULL CHECK(amount_minor>0), currency char(3) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_ledger_entries_journal ON ledger_entries(journal_id);
CREATE INDEX ix_ledger_entries_account_created ON ledger_entries(account_id,created_at DESC);
CREATE TABLE tutor_payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), amount_minor bigint NOT NULL CHECK(amount_minor>0), currency char(3) NOT NULL DEFAULT 'BDT', status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','paid','failed','reversed')), provider text, provider_reference text, idempotency_key text NOT NULL UNIQUE, requested_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz);
CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), reviewer_user_id uuid NOT NULL REFERENCES users(id), tutor_user_id uuid NOT NULL REFERENCES tutor_profiles(user_id), rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5), review_text text, moderation_status text NOT NULL DEFAULT 'pending' CHECK(moderation_status IN ('pending','published','hidden','rejected')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(booking_id,reviewer_user_id));
CREATE TABLE support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_user_id uuid NOT NULL REFERENCES users(id), assigned_to uuid REFERENCES users(id), category text NOT NULL, subject text NOT NULL, description text NOT NULL, priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','waiting_for_user','resolved','closed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE TABLE disputes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), opened_by uuid NOT NULL REFERENCES users(id), assigned_to uuid REFERENCES users(id), category text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','investigating','awaiting_response','resolved','rejected','appealed')), resolution_code text, resolution_notes text, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE TABLE tutor_replacement_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), requested_by uuid NOT NULL REFERENCES users(id), reason_code text NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','reviewing','matching','offered','accepted','closed','rejected')), replacement_tutor_user_id uuid REFERENCES tutor_profiles(user_id), outcome_notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid REFERENCES users(id), action text NOT NULL, resource_type text NOT NULL, resource_id text, request_id text, reason text, safe_metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_audit_resource_created ON audit_logs(resource_type,resource_id,created_at DESC);
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), last_error_code text);
CREATE INDEX ix_outbox_pending ON outbox_events(created_at) WHERE published_at IS NULL;
CREATE TABLE idempotency_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope text NOT NULL, idempotency_key text NOT NULL, request_hash text NOT NULL, status text NOT NULL CHECK(status IN ('processing','completed','failed')), resource_type text, resource_id uuid, response_status integer, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope,idempotency_key));
CREATE TABLE system_settings (key text PRIMARY KEY, value jsonb NOT NULL, description text, updated_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feature_flags (key text PRIMARY KEY, enabled boolean NOT NULL DEFAULT false, rules jsonb NOT NULL DEFAULT '{}'::jsonb, updated_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE auth_verification_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, contact text NOT NULL, purpose text NOT NULL CHECK(purpose IN ('contact_verification','password_recovery','login_2fa')), code_hash text NOT NULL, attempts integer NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_auth_verification_contact_purpose ON auth_verification_codes(contact, purpose, expires_at) WHERE verified_at IS NULL;
CREATE INDEX ix_auth_verification_user_id ON auth_verification_codes(user_id);

-- Production follow-ups: recurring rule tables, organization tenancy, policy snapshots, deferred ledger balancing, full locality hierarchy, data retention, provider settlement imports, evidence/comment tables and consent workflow. Resolve and test before those features ship.
